const params=new URLSearchParams(location.search);
const variant=['a','b','c'].includes(params.get('variant'))?params.get('variant'):'a';
const views=['lobby','battle','collection','loadout','tutorial','settings','result'];
let view=views.includes(params.get('screen'))?params.get('screen'):'lobby',part='Head',selected=5,step=1;
const app=document.getElementById('app'),dialogs=document.getElementById('dialogs');
const skills=window.NEON_SKILLS;
const symbols={arrow:'<path d="M4 12h16M14 6l6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',star:'<path d="m12 2 2.6 7.4L22 12l-7.4 2.6L12 22l-2.6-7.4L2 12l7.4-2.6Z"/>',settings:'<path d="m9 3-.7 3.1-2.8 1.6L2.6 7l-1 1.7 2.2 2.3v3L2 16.3 3 18l3.1-.8 2.8 1.6L9.6 22h2.8l.7-3.2 2.8-1.6 3.1.8 1-1.7-1.8-2.3v-3l2.2-2.3-1-1.7-2.9.7-2.8-1.6L12.9 3Z"/><circle cx="10.9" cy="12.4" r="3"/>',grid:'<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/>',duel:'<path d="m5 3 16 16-2 2L3 5V3Zm14 0L3 19l2 2L21 5V3ZM2 15l7 7M15 22l7-7"/>',play:'<path d="m8 4 12 8-12 8Z"/>',check:'<path d="m4 12 5 5L20 6"/>',book:'<path d="M12 5C8 2 5 3 2 3v16c4 0 7-1 10 2 3-3 6-2 10-2V3c-3 0-6-1-10 2Zm0 0v16"/>',volume:'<path d="m11 4-6 5H2v6h3l6 5Zm5 3c4 2 4 8 0 10m3-13c7 4 7 12 0 16"/>'};
function icon(name,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round" stroke-linecap="round">${symbols[name]||symbols.star}</svg>`;}
function art(s,cls=''){return `<svg class="skill-art ${cls}" role="img" aria-label="${s.name}" viewBox="${s.viewBox.join(' ')}"><image href="assets/${s.file}" width="${s.size[0]}" height="${s.size[1]}"/></svg>`;}
function button(text,action,cls='',glyph=''){return `<button class="btn ${cls}" data-action="${action}">${glyph?icon(glyph):''}<span>${text}</span>${cls.includes('primary')?icon('arrow'):''}</button>`;}
function utility(text,action,glyph){return `<button class="utility" data-action="${action}" aria-label="${text}">${icon(glyph)}<span>${text}</span></button>`;}
function brand(){return '<div class="brand">NEON <em>IMPACT</em></div>';}
function scene(){return `<div class="scenery" aria-hidden="true"><img class="scene-hand" src="assets/hand.png" alt=""><img class="cloud cloud-one" src="assets/cloud1.png" alt=""><img class="cloud cloud-two" src="assets/cloud3.png" alt=""><div class="stars"></div></div>`;}
function head(title,extra=''){return `<header class="screen-head"><div class="page-heading">${utility('返回','lobby','back')}<h1>${title}</h1></div>${extra}</header>`;}
function lobby(){return `${scene()}<header class="lobby-head">${brand()}<div class="top-tools"><span class="currency">${icon('star')}59</span>${utility('設定','settings','settings')}</div></header><div class="lobby-layout"><section class="lobby-menu"><label class="player-label" for="player-name">玩家名稱</label><div class="name-field"><span class="player-mark">N</span><input id="player-name" value="Guest" maxlength="24" autocomplete="off" aria-label="玩家名稱"></div><div class="mode-list">${button('<strong>無際戰場</strong><small>收集星星・取得技能・生存</small>','battle','primary mode','play')}${button('<strong>頂尖對決</strong><small>選擇五項技能，迎戰對手</small>','loadout','secondary mode','duel')}</div><div class="lobby-links">${button('收藏','collection','tertiary','grid')}${button('遊玩教學','tutorial','tertiary','book')}</div><div class="unavailable"><span>組隊競技</span><span>尚未開放</span></div></section><figure class="guardian-stage"><div class="orbit" aria-hidden="true"></div><img src="assets/god.png" alt="造星神"><figcaption aria-hidden="true"><span></span>${icon('star')}<span></span></figcaption></figure></div>`;}
function battle(){return `${scene()}<div class="arena" aria-label="戰鬥場景示意"><img class="arena-god" src="assets/god.png" alt=""><div class="actor ally"><span class="direction-mark"></span><img src="assets/knight.png" alt="我方角色"><span class="actor-name">Guest</span></div><div class="actor enemy"><img src="assets/anubis.png" alt="敵方角色"><span class="actor-name">Neon Bot 512</span></div><div class="actor enemy second"><img src="assets/beetle.png" alt="敵方角色"><span class="actor-name">Neon Bot 989</span></div><div class="projectile p1"></div><div class="projectile p2"></div><div class="loot l1">✦</div><div class="loot l2">✦</div><div class="loot l3">✦</div></div><aside class="combat-feed"><p><span>你</span> 擊敗 Neon Bot 387</p><p>Neon Bot 989 達到等級 4</p></aside><div class="rank-area">${utility('離開戰場','leave','back')}<section class="leaderboard"><h2>排行榜</h2><ol><li><span>01</span><span>Neon Bot 989</span><b>18</b></li><li class="you"><span>02</span><span>Guest <small>你</small></span><b>12</b></li><li><span>03</span><span>Neon Bot 512</span><b>9</b></li></ol></section></div><section class="health-panel" aria-label="生命與等級"><div class="health-top"><span class="level">LV <b>4</b></span><strong>850 <span>/ 1000</span></strong></div><div class="health-track"><span></span></div><div class="health-bottom"><span>生命</span><span>${icon('star')}128</span></div></section><section class="skill-dock" aria-label="自動施放技能狀態">${[skills[4],skills[11],skills[20]].map((s,i)=>`<div class="skill-state ${i===1?'cooling':''}">${art(s)}<span class="cooldown">${i===1?'2.4':''}</span><span class="skill-part">${['頭部','身體','背部'][i]}</span><i class="ready-line"></i></div>`).join('')}</section>`;}
function collection(){const data=skills.filter(s=>s.part===part),s=data.find(s=>s.id===selected)||data[0];selected=s.id;return `${head('收藏','<span class="available">95 項技能・全部可用</span>')}<div class="collection-layout"><section class="catalogue"><nav class="part-tabs" aria-label="技能部位">${['Head','Body','Back'].map((p,i)=>`<button class="part-tab ${p===part?'selected':''}" data-part="${p}" aria-pressed="${p===part}">${['頭部','身體','背部'][i]}</button>`).join('')}</nav><div class="skill-grid">${data.map(s=>`<button class="skill-card ${s.id===selected?'selected':''}" data-skill="${s.id}" aria-pressed="${s.id===selected}">${art(s)}<span>${s.name}</span>${s.id===selected?icon('check','selected-mark'):''}</button>`).join('')}</div></section><aside class="skill-detail"><div class="detail-art">${art(s)}</div><div class="detail-copy"><span class="detail-type">${{Head:'頭部',Body:'身體',Back:'背部'}[part]}</span><h2>${s.name}</h2><p>${s.description}</p></div>${button('前往配裝','loadout','primary')}</aside></div>`;}
function loadout(){return `${head('頂尖對決',utility('遊玩教學','tutorial','book'))}<section class="loadout"><div class="loadout-heading"><h2>選擇五項技能</h2><p>點選欄位，調整本次對決的技能。</p></div><div class="loadout-grid">${[skills[4],skills[1],skills[10],skills[14],skills[21]].map((s,i)=>`<button class="loadout-slot" data-action="collection"><span class="slot-index">0${i+1}</span>${art(s)}<strong>${s.name}</strong><span class="slot-change">更換 ${icon('arrow')}</span></button>`).join('')}</div><div class="loadout-foot"><span>Guest</span>${button('開始配對','match','primary')}</div></section>`;}
const guideSteps=[['遊戲目標','收集星星，提升等級與技能。','在戰場中生存，擊敗其他玩家。'],['角色操作','<span class="desktop-copy">移動滑鼠，角色會朝游標方向移動。</span><span class="touch-copy">按住畫面，角色會朝手指方向移動。</span>','<span class="desktop-copy">將游標移回中央，即可停止移動。</span><span class="touch-copy">將手指移回中央，即可停止移動。</span>'],['攻擊方向','方向指針表示角色移動與攻擊的方向。','用指針碰撞敵人，可以造成傷害與擊退。'],['星星與等級','收集戰場上的星星來提升等級。','注意左下角的生命值與等級。'],['技能施放','獲得的技能會依規則自動施放。','右下角可查看頭部、身體與背部技能狀態。'],['狀態效果','戰鬥中的攻擊可能附帶不同狀態效果。','觀察角色與技能狀態，保持移動。'],['準備出戰','無際戰場會在戰鬥中取得技能。','頂尖對決則在出戰前選擇五項技能。']];
function tutorial(){const g=guideSteps[step];return `${scene()}<section class="guide-panel"><header class="guide-head"><span class="section-label">遊玩教學</span>${utility('關閉','lobby','close')}</header><div class="guide-layout"><div class="guide-demo" aria-hidden="true"><div class="guide-boundary"><span class="guide-axis axis-x"></span><span class="guide-axis axis-y"></span><img src="assets/knight.png" alt=""><div class="guide-travel"></div><div class="guide-touch"></div></div></div><div class="guide-copy"><span class="step-label">${String(step+1).padStart(2,'0')}</span><h1>${g[0]}</h1><ol><li>${g[1]}</li><li>${g[2]}</li></ol>${step===1?'<p class="hint">技能會自動施放。</p>':''}</div></div><footer class="guide-foot"><button class="btn secondary" data-action="previous" ${step===0?'disabled':''}>${icon('back')}上一頁</button><span class="page-count">${step+1} <span>/ 7</span></span>${button(step===6?'開始遊玩':'下一頁',step===6?'battle':'next','primary')}</footer></section>`;}
function settings(){return `${head('設定')}<div class="settings-layout"><nav class="settings-nav" aria-label="設定分類"><button class="selected" data-setting="general" aria-pressed="true">一般設定</button><button data-setting="shouts" aria-pressed="false">喊話設定</button><button data-setting="credits" aria-pressed="false">製作名單</button></nav><section class="settings-content" id="settings-content">${generalSettings()}</section></div>`;}
function generalSettings(){return `<div class="setting-group"><h2>聲音</h2><label class="setting-row"><span>音樂音量</span><div class="range-field"><input type="range" min="0" max="100" value="70" aria-label="音樂音量"><output>70%</output></div></label><label class="setting-row"><span>音效音量</span><div class="range-field"><input type="range" min="0" max="100" value="85" aria-label="音效音量"><output>85%</output></div></label></div><div class="setting-group"><h2>一般</h2><label class="setting-row"><span>語言</span><select aria-label="語言"><option>繁體中文</option><option>English</option></select></label><label class="setting-row"><span>連線地區</span><select aria-label="連線地區"><option>Asia</option><option>Hong Kong</option></select></label><p class="setting-note">地區設定會套用至下一次連線。</p></div><div class="settings-actions">${button('遊玩教學','tutorial','secondary','book')}</div>`;}
function result(){return `${scene()}<section class="result-panel"><h1>戰鬥結算</h1><div class="result-stats"><div class="stat featured"><span>擊敗數</span><strong>12</strong></div><div class="stat"><span>生存時間</span><strong>3<small>分</small>42<small>秒</small></strong></div><div class="stat"><span>獲得星星</span><strong>${icon('star')}128</strong></div></div><p class="record">最佳擊敗數 <b>18</b></p><div class="result-actions">${button('返回大廳','lobby','secondary')}${button('再次出戰','battle','primary')}</div></section>`;}
function render(){app.className=`game variant-${variant} view-${view}`;app.innerHTML=({lobby,battle,collection,loadout,tutorial,settings,result})[view]();dialogs.innerHTML='';history.replaceState(null,'',`?variant=${variant}&screen=${view}`);if(parent!==window)parent.postMessage({type:'neon-ui-view',view,variant},location.origin);document.title=`Neon Impact · ${variant.toUpperCase()} · ${{lobby:'大廳',battle:'戰鬥',collection:'收藏',loadout:'配裝',tutorial:'教學',settings:'設定',result:'結算'}[view]}`;}
function modal(title,message,primary,cancel,action){dialogs.innerHTML=`<div class="dialog-shade"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">${title}</h2><p>${message}</p><div class="dialog-actions">${button(cancel,'dismiss','secondary')}${button(primary,action,'primary')}</div></section></div>`;dialogs.querySelector('button')?.focus();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.part){part=b.dataset.part;selected=skills.find(s=>s.part===part).id;render();return;}if(b.dataset.skill){selected=Number(b.dataset.skill);render();return;}if(b.dataset.setting){document.querySelectorAll('[data-setting]').forEach(el=>{el.classList.toggle('selected',el===b);el.setAttribute('aria-pressed',String(el===b));});document.getElementById('settings-content').innerHTML=b.dataset.setting==='general'?generalSettings():b.dataset.setting==='shouts'?'<div class="setting-group"><h2>喊話設定</h2><label class="setting-row"><span>升級</span><input class="shout-input" aria-label="升級喊話" placeholder="輸入喊話內容" maxlength="40"></label><label class="setting-row"><span>擊敗對手</span><input class="shout-input" aria-label="擊敗對手喊話" placeholder="輸入喊話內容" maxlength="40"></label></div>'+button('儲存喊話','save','primary'):'<div class="setting-group"><h2>製作名單</h2><p>NEON IMPACT</p><p class="setting-note">Starbro</p></div>';return;}const a=b.dataset.action;if(views.includes(a)){view=a;render();}else if(a==='next'||a==='previous'){step=Math.max(0,Math.min(6,step+(a==='next'?1:-1)));render();}else if(a==='leave')modal('離開戰場？','離開後會返回大廳。','離開戰場','繼續遊玩','lobby');else if(a==='match')modal('配對中','正在尋找對手…','預覽對戰','取消配對','battle');else if(a==='save')modal('已儲存','設計展示不會寫入正式存檔。','完成','返回','dismiss');else if(a==='dismiss')dialogs.innerHTML='';});
document.addEventListener('input',e=>{if(e.target.matches('input[type="range"]'))e.target.nextElementSibling.value=e.target.value+'%';});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(dialogs.innerHTML)dialogs.innerHTML='';else{view='lobby';render();}}if(e.key==='Tab'&&dialogs.innerHTML){const a=[...dialogs.querySelectorAll('button')],first=a[0],last=a.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}});
render();
